return {rwnpc01={id="rwnpc01",dsc="她生性活泼，头挽垂髻，身着一袭广袖红裙，本是红娘堂里的一名普通“红娘”，平素帮人牵拉红线，缔结良缘。听闻她手中的姻缘簿上记载着不少待牵红线的花名，引得江湖上的诸多侠侣均想一窥。",sex="女",age=18,looks=21,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="他是泰安城的名捕。他身穿捕快服饰，但丝毫不能掩盖光华气质。虽然气质出众，不过看起来却懒洋洋的。",sex="男",age=20,looks=26,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="他行走四方，在各地淘寻古董奇珍，但在江湖上的名气却好坏掺半，有说其诚信为商，也有说其奸诈为商。",sex="男",age=45,looks=19,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="盗墓世家临淄夏侯之后。本名夏侯燕，幼时崇拜盗圣惊鸿雁的传说，自名为惊鸿燕。喜好盗墓，且技艺高超，所到之处寸草不生。",sex="女",age=19,looks=21,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",dsc="“目不识丁，三坟五典”便是他名字的由来。他本是一个普通的武林世家子弟，一次机缘巧合下习得了绝世武功，他的人生也因此发生了翻天覆地的变化。",sex="男",age=27,looks=25,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="一个专门卖花的商人。",sex="男",age=50,looks=17,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="她眉目间恍若秋水暗波，周身气质淡若清菊，再衬上一袭嫩黄似绿的长裙，便如山间寒霜下蕴藏的一株“绿玉如意”。",sex="女",age=22,looks=23,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",dsc="凌府的丫环，伺候凌小姐多年，对凌小姐忠心耿耿。",sex="女",age=18,looks=18,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="落月山庄的一名弟子。目若秋水，风度翩翩，笑容让人捉摸不定。",sex="男",age=20,looks=23,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="他是一位卖烟花的商人，高高胖胖，总是面带和蔼的笑容。",sex="男",age=42,looks=17,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="她是落月山庄弟子，年纪轻轻武功十分不凡，她身穿一袭红衣，煞是显眼。",sex="女",age=20,looks=23,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="她本是慕容家的一名婢女，后于江湖中邂逅萧大侠，自此生死相随。",sex="女",age=18,looks=22,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="他便是江湖中赫赫有名的萧大侠，他因身世而远走天涯，并卷入了一场江湖恶斗。",sex="男",age=30,looks=25,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="她是朱姑娘的妹妹，自小在天狼长大，故而性情阴狠毒辣，唯有对待萧大侠一人有所不同。",sex="女",age=18,looks=20,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="他微微佝偻着背，是平安小镇中出了名的毛贼，平日里偷鸡摸狗，便是仗着几分武艺到处逞凶。",sex="男",age=22,looks=18,showequip={},withCorpse=0},rwnpc16={id="rwnpc16",dsc="他昔年是伏龙山的堂主，如今已经脱离伏龙，成了个名副其实的游侠。据闻他曾与伏龙帮主有约，待武艺大成之日，结昔日之约。",sex="男",age=22,looks=27,showequip={},withCorpse=0},rwnpc17={id="rwnpc17",dsc="言笑略带青涩，如三月初蕊见之难忘。但矛盾的是，那骨子里隐隐的傲气又似蔷薇多刺，不由的吸引你多看上几眼。",sex="女",age=17,looks=27,showequip={},withCorpse=0},rwnpc18={id="rwnpc18",dsc="一位卖面具的老人，穿一身洗得发白的布衣，他制作的面具精美，颇受欢迎。",sex="男",age=52,looks=17,showequip={},withCorpse=0},rwnpc19={id="rwnpc19",dsc="她医术高超，能施得金针封穴绝技，面慈心善，经常外出行医，帮助他人。",sex="女",age=20,looks=21,showequip={},withCorpse=0},rwnpc20={id="rwnpc20",dsc="她戴着一张蓝纹白狐狸面具，只露出下半张脸，身上隐约有草药的药香。",sex="女",age=20,looks=21,showequip={},withCorpse=0},rwnpc21={id="rwnpc21",dsc="他是武当派弟子，面目俊秀，气质文质彬彬，却隐约有股彪悍之意叫人不敢小瞧，江湖上人称张大侠。",sex="男",age=32,looks=28,showequip={},withCorpse=0},rwnpc22={id="rwnpc22",dsc="他是卖河灯的老人，脸上总是挂着和蔼的笑容。",sex="男",age=60,looks=18,showequip={},withCorpse=0},rwnpc23={id="rwnpc23",dsc="他是卖杂货的商贩，并不常出现在此处。",sex="男",age=32,looks=18,showequip={},withCorpse=0},rwnpc24={id="rwnpc24",dsc="容貌娇艳无伦，为人亦正亦邪，如今她隐藏身份来到平安小镇，与张大侠仿若一对普通夫妻，江湖人称小妖女。",sex="女",age=32,looks=28,showequip={},withCorpse=0},rwnpc25={id="rwnpc25",dsc="他带着巨大的斗笠，看不清容貌，身着一袭青衫，腰间别着暗纹雕刻的酒葫芦。",sex="男",age=25,looks=24,showequip={},withCorpse=0},bsnpc01={id="bsnpc01",dsc="他为人十分老实，少年时本打算考取功名，可惜家道中落，于是学着别人落草为寇，但因为十分老实被赶出了山寨，如今耕田过日子倒也自在。",sex="男",age=29,looks=16,showequip={},withCorpse=0},bsnpc02={id="bsnpc02",dsc="他昔年曾是一名刀客，后被仇人追杀身负重伤，为平安小镇的居民所救，后在此安家退隐江湖。",sex="男",age=45,looks=15,showequip={},withCorpse=0},bsnpc03={id="bsnpc03",dsc="她是平安小镇的居民，在家中排行第二，早年嫁给了一个江湖浪人，后夫君远走江湖再未归来。",sex="女",age=44,looks=18,showequip={},withCorpse=0},bsnpc04={id="bsnpc04",dsc="她身着破旧的粗布衣，身上挂着用线绳穿好的十多双大大小小的草鞋、布鞋。",sex="女",age=45,looks=18,showequip={},withCorpse=0},bsnpc05={id="bsnpc05",dsc="他一副书生模样，但手中却拿着一个沉重的流星锤，虽是有模有样的耍着，但因气力不足，下盘紊乱，常常将流星锤砸入四周的石板，引得周围人群纷纷避让。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc06={id="bsnpc06",dsc="他是平安小镇中出了名的恶霸，仗着家中有人当官平日里作威作福。",sex="男",age=28,looks=18,showequip={},withCorpse=0},bsnpc07={id="bsnpc07",dsc="她刚刚搬到平安小镇，生得颇有几分姿色，故引得临街儿郎思慕不已，扯出一段“倚门回首，却把青梅嗅”的佳话。",sex="女",age=23,looks=20,showequip={},withCorpse=0},bsnpc08={id="bsnpc08",dsc="他梳着一个长长的小辫，手上拿着一把桃木短剑，面目严肃，颇有几分“大侠”的样子。",sex="男",age=11,looks=19,showequip={},withCorpse=0},bsnpc09={id="bsnpc09",dsc="他时常喝得酩酊大醉，听说多年前也曾是浪荡江湖的剑客，后来不知为何埋剑藏名隐居于平安小镇。",sex="男",age=45,looks=20,showequip={},withCorpse=0},bsnpc10={id="bsnpc10",dsc="他手中拿着几个铜板，正盯着前方的菜来饭馆，不时往前走两步，又退两步，看起来十分纠结。",sex="男",age=23,looks=17,showequip={},withCorpse=0},bsnpc11={id="bsnpc11",dsc="他是平安小镇的居民，身穿粗布长衣，手中拿着一个鸟笼。鸟笼里关着一只翠鸟，毛色翠兰，十分夺目。",sex="男",age=35,looks=16,showequip={},withCorpse=0},bsnpc12={id="bsnpc12",dsc="他自称是响当当的江湖大侠，身具传奇，懂得天下所有武功。他手中时常抱着剑，装成一副十分冷酷的样子。",sex="男",age=35,looks=18,showequip={},withCorpse=0},bsnpc13={id="bsnpc13",dsc="他佝偻着背，手上拿着一个拐杖，正坐在路旁歇息。",sex="男",age=65,looks=15,showequip={},withCorpse=0},bsnpc14={id="bsnpc14",dsc="她个头要比同龄孩童还要小巧些，走起路来摇摇晃晃，手中拿着一个冰糖葫芦，笑嘻嘻的望着你。",sex="女",age=10,looks=18,showequip={},withCorpse=0},bsnpc15={id="bsnpc15",dsc="她是平安小镇的居民，父母常年在外，由祖母一手带大，十分懂事。",sex="女",age=10,looks=18,showequip={},withCorpse=0},bsnpc16={id="bsnpc16",dsc="他是平安小镇的居民，手中拿着一个鸡腿，胸前的衣襟沾满了油渍。",sex="男",age=35,looks=18,showequip={},withCorpse=0},bsnpc17={id="bsnpc17",dsc="她年轻时曾是武林中公认的美人，英雄迟暮，美人自然也有这么一天，自隐居平安小镇后，她除了自怜自哀以外成了统领平安小镇三姑六婆一起八卦的核心之人。",sex="女",age=45,looks=21,showequip={},withCorpse=0},bsnpc18={id="bsnpc18",dsc="她是平安小镇的居民，听闻早年逃荒而来，她的青梅竹马则于半道饿死，致使其一生未嫁。",sex="女",age=56,looks=18,showequip={},withCorpse=0},bsnpc19={id="bsnpc19",dsc="他是村中顽童，父亲是个马商，故小名叫“马儿”，日子久了大家反而忘记了他原本的名字。他跨着一个竹马，正学着戏文的那些江湖豪杰“行侠仗义”。",sex="男",age=10,looks=17,showequip={},withCorpse=0},bsnpc20={id="bsnpc20",dsc="他是平安小镇的居民，有几分小聪明，去年做了点小生意赚了不少钱，在镇中出了名的怕老婆，常常被罚跪搓衣板。",sex="男",age=33,looks=19,showequip={},withCorpse=0},bsnpc21={id="bsnpc21",dsc="他是平安小镇的居民，本是个教书先生，据说年轻时曾经中过举人，但是真是假不得而知。",sex="男",age=55,looks=16,showequip={},withCorpse=0},bsnpc22={id="bsnpc22",dsc="他是一个马贩，常年在外奔波，不久前在去往西域时被沙匪所劫，幸得江湖中的侠客路过救了他一命。可惜他身受重伤，落下了病根，自此不宜远行。",sex="男",age=35,looks=17,showequip={},withCorpse=0},bsnpc23={id="bsnpc23",dsc="他手上拿着一把钉耙，听说自小就想成为游走江湖的大侠，可惜祖上代代务农，故其父不允其出门学艺。",sex="男",age=21,looks=19,showequip={},withCorpse=0},bsnpc24={id="bsnpc24",dsc="他是平安小镇的居民，曾是附近县里头的师爷，公正无私，协助官老爷处理了不少冤案。在镇中颇有几分声望，受到邻里的尊重。",sex="男",age=55,looks=17,showequip={},withCorpse=0},bsnpc25={id="bsnpc25",dsc="他是平安小镇的普通居民，平日里都在田间务农，虽然大字不识几个，却喜欢观摩镇中老者下棋，故而看上去略给人几分聪慧之感。",sex="男",age=24,looks=18,showequip={},withCorpse=0},bsnpc26={id="bsnpc26",dsc="她走起路来颇有几分“婀娜”之感，听闻早年流落风尘被一名侠客所救，如今在这平安小镇里安度余生。",sex="女",age=43,looks=18,showequip={},withCorpse=0},bsnpc27={id="bsnpc27",dsc="他是一个江湖侠客，身后背着一把极为沉重的巨剑，名为“战戈”。他脸上有一道疤痕，不知是从何而来，下巴处许久没有打理的胡渣让他看上去十分沧桑。",sex="男",age=45,looks=23,showequip={},withCorpse=0},bsnpc28={id="bsnpc28",dsc="他是平安小镇的居民，曾在武馆学艺多年，如今在镇中教习些拳脚。",sex="男",age=27,looks=16,showequip={},withCorpse=0},bsnpc29={id="bsnpc29",dsc="他穿着朴素，此时正在安排一些苦力搬运货物。",sex="男",age=35,looks=20,showequip={},withCorpse=0},bsnpc30={id="bsnpc30",dsc="他是马三德的独子，自幼顽皮，跟他父亲一样不喜欢读书，整日从私塾里逃出来胡闹，自称天下没人能够管住他。",sex="男",age=10,looks=20,showequip={},withCorpse=0},bsnpc31={id="bsnpc31",dsc="他本是穷苦人家出生，识不得几个大字，少年时跟随一个药商做学徒，十年后凭借运气发了家，积累了些小财，娶妻生子。自发妻去世后搬离了原本的村子，来到平安小镇居住。",sex="男",age=45,looks=17,showequip={},withCorpse=0},bsnpc32={id="bsnpc32",dsc="他是平安小镇的糖贩，家中养了无数蜜蜂，做出的糖极为甜蜜。他为人亲和，时常会把自己做的各色糖果赠予镇中孩童。",sex="男",age=32,looks=17,showequip={},withCorpse=0}}00